#!/usr/bin/env python3
"""Extract readable text from a claude session JSONL transcript.
Usage: extract.py <file> [start_line] [end_line]
Prints per JSONL-line: line index, type, role, and flattened text content.
"""
import json, sys

def text_of(msg):
    """Return list of (kind, text) tuples from a message dict."""
    out=[]
    if not isinstance(msg, dict):
        return out
    content = msg.get('content')
    if isinstance(content, str):
        out.append(('text', content))
    elif isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                out.append(('raw', str(block))); continue
            bt = block.get('type','')
            if bt == 'text':
                out.append(('text', block.get('text','')))
            elif bt == 'thinking':
                out.append(('thinking', block.get('thinking','')))
            elif bt == 'tool_use':
                name = block.get('name','')
                inp = block.get('input',{})
                out.append(('tool_use:'+name, json.dumps(inp)[:6000]))
            elif bt == 'tool_result':
                c = block.get('content','')
                if isinstance(c, list):
                    parts=[]
                    for cc in c:
                        if isinstance(cc,dict) and cc.get('type')=='text':
                            parts.append(cc.get('text',''))
                        else:
                            parts.append(str(cc))
                    c='\n'.join(parts)
                out.append(('tool_result', str(c)))
            else:
                out.append((bt or 'block', json.dumps(block)[:2000]))
    return out

def main():
    f=sys.argv[1]
    start=int(sys.argv[2]) if len(sys.argv)>2 else 0
    end=int(sys.argv[3]) if len(sys.argv)>3 else 10**9
    with open(f) as fh:
        for i,line in enumerate(fh):
            if i<start: continue
            if i>end: break
            line=line.strip()
            if not line: continue
            try:
                o=json.loads(line)
            except:
                print(f'=== L{i} PARSE-ERR ==='); continue
            t=o.get('type','')
            msg=o.get('message',{})
            role = msg.get('role','') if isinstance(msg,dict) else ''
            att = o.get('attachment')
            if t=='attachment' and att is not None:
                s=json.dumps(att)
                print(f'=== L{i} [attachment] ===')
                print(s[:3000])
                continue
            blocks=text_of(msg)
            if not blocks:
                continue
            print(f'=== L{i} [{t}/{role}] ===')
            for kind,txt in blocks:
                print(f'--- {kind} ---')
                print(txt)

if __name__=='__main__':
    main()

