#!/usr/bin/env python3
import json, sys, re

TERMS = ['upgrad','deep_s3','deep_s4','postedit','post-edit','FWD_PIPE','SUBTILE','P1-epilogue','P1_SUBTILE',
         'roofline','1.49','4.02','2.05','BUG-04','prebuilt','optimizer-max','gate-hardening','C0 emitter',
         'dectc_codegen','DW_STAGE','FWD_STAGES','megakernel','wgmma','keep','revert','TODO','open queue',
         'handoff','final-state','L3-TC','L3TC','baked','lever']
pat = re.compile('|'.join(re.escape(t) for t in TERMS), re.I)

def flat(msg):
    s=[]
    if not isinstance(msg,dict): return ''
    c=msg.get('content')
    if isinstance(c,str): return c
    if isinstance(c,list):
        for b in c:
            if not isinstance(b,dict): continue
            bt=b.get('type','')
            if bt=='text': s.append(b.get('text',''))
            elif bt=='thinking': s.append(b.get('thinking',''))
            elif bt=='tool_use': s.append(json.dumps(b.get('input',{})))
            elif bt=='tool_result':
                cc=b.get('content','')
                s.append(json.dumps(cc) if not isinstance(cc,str) else cc)
    return '\n'.join(s)

f=sys.argv[1]
with open(f) as fh:
    for i,line in enumerate(fh):
        line=line.strip()
        if not line: continue
        try: o=json.loads(line)
        except: continue
        t=o.get('type','')
        txt = flat(o.get('message',{}))
        if t=='attachment':
            txt += json.dumps(o.get('attachment',''))
        if pat.search(txt):
            # collect which terms hit
            hits=sorted(set(m.group(0).lower() for m in pat.finditer(txt)))
            role=o.get('message',{}).get('role','') if isinstance(o.get('message'),dict) else ''
            print(f'L{i} [{t}/{role}] len={len(txt)} terms={hits[:12]}')
